Create enemyGeneration.ts utility:
- Scale enemy stats based on current round number
- Increase enemy count or introduce new enemy types
- Balance difficulty curve to be challenging but fair
- Maintain variety in enemy compositions

Enemy scaling implementation:
```typescript
export const generateEnemiesForRound = (roundNumber: number): Enemy[] => {
  const baseStats = { health: 100, attack: 20, defense: 5 };
  const scalingFactor = 1 + (roundNumber - 1) * 0.2; // 20% increase per round

  const enemyCount = Math.min(1 + Math.floor(roundNumber / 3), 4); // Max 4 enemies

  return Array.from({length: enemyCount}, (_, i) => ({
    id: `enemy-${roundNumber}-${i}`,
    name: `Enemy ${i + 1}`,
    health: Math.floor(baseStats.health * scalingFactor),
    maxHealth: Math.floor(baseStats.health * scalingFactor),
    attack: Math.floor(baseStats.attack * scalingFactor),
    defense: Math.floor(baseStats.defense * scalingFactor)
  }));
};
```
